async function checkRelease(){if(!currentUser||document.hidden||!navigator.onLine)return;try{const r=await fetch('/health',{cache:'no-store'});if(r.ok){const body=await r.json();if(/^\d+\.\d+\.\d+$/.test(body.version)){latestVersion=body.version;refreshBell();}}}catch{}}
let wisdomCache=null,teacherCache=null,welcomeLoading=false,welcomeSession=new Set();
function welcomeDay(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function wisdomIndex(day,count){return Math.floor((Date.parse(day+'T00:00:00Z')-Date.parse('2026-10-24T00:00:00Z'))/86400000+count*1000)%count;}
function welcomeSlot(now=new Date()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',hourCycle:'h23'}).formatToParts(now),v=Object.fromEntries(parts.map(p=>[p.type,p.value])),hour=Number(v.hour),slot=hour<5?3:hour<11?0:hour<14?1:hour<18?2:3,calendarDay=v.year+'-'+v.month+'-'+v.day,day=hour<5?new Date(Date.parse(calendarDay+'T00:00:00Z')-86400000).toISOString().slice(0,10):calendarDay;return {day,slot,label:['Buổi sáng','Buổi trưa','Buổi chiều','Buổi tối'][slot],serial:Math.floor(Date.parse(day+'T00:00:00Z')/86400000)*4+slot};}
// Pure selection functions are embedded into welcome.js at build-authoring time.
// Every excerpt occurs exactly once in a complete cycle, including authors
// without a profile. Entries for each author are spread across the cycle.
function welcomeProfile(author, profiles) {
  return profiles.filter(p => author === p.name || author.startsWith(p.name + ' ·'))
    .sort((a,b) => b.name.length - a.name.length)[0];
}
function welcomeHash(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}
function welcomeDeck(quotes, profiles) {
  const groups = new Map();
  for (const quote of quotes) {
    if (typeof quote.vi !== 'string' || !quote.vi.trim()) continue;
    const profile = welcomeProfile(quote.author, profiles);
    const key = profile?.id || quote.author;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push({quote,profile});
  }
  const deck = [];
  for (const [key, entries] of groups) {
    entries.sort((a,b) => welcomeHash(a.quote.id || a.quote.vi) - welcomeHash(b.quote.id || b.quote.vi)
      || a.quote.vi.localeCompare(b.quote.vi));
    entries.forEach((entry,i) => deck.push({...entry, position:(i+0.5)/entries.length,key}));
  }
  return deck.sort((a,b) => a.position - b.position || a.key.localeCompare(b.key));
}
let welcomeDeckCache=null,welcomeDeckQuotes=null,welcomeDeckProfiles=null;
function welcomeSelection(time) {
  const profiles=teacherCache?.profiles||[];
  if(welcomeDeckQuotes!==wisdomCache||welcomeDeckProfiles!==profiles){
    welcomeDeckCache=welcomeDeck(wisdomCache,profiles);
    welcomeDeckQuotes=wisdomCache;welcomeDeckProfiles=profiles;
  }
  if(!welcomeDeckCache.length)return {};
  const epoch=Math.floor(Date.parse('2026-10-24T00:00:00Z')/86400000)*4;
  const index=((time.serial-epoch)%welcomeDeckCache.length+welcomeDeckCache.length)%welcomeDeckCache.length;
  return welcomeDeckCache[index];
}

async function dailyWelcome(){if(!currentUser||document.hidden||welcomeLoading||$('#editor').open||document.querySelector('.welcome-dialog'))return;const owner=currentUser.id,time=welcomeSlot(),day=time.day,key='zen-welcome:'+owner+':'+day+':'+time.slot;if(localRead(key)||welcomeSession.has(key))return;welcomeLoading=true;try{if(!wisdomCache){const response=await fetch('/wisdom.json');if(!response.ok)throw Error('wisdom');wisdomCache=(await response.json()).filter(q=>typeof q.vi==='string'&&q.vi.trim());}if(!teacherCache){const response=await fetch('/teachers.json');if(response.ok)teacherCache=await response.json();}if(!currentUser||currentUser.id!==owner||$('#editor').open)return;const {quote:q,profile}=welcomeSelection(time);if(!q)return;const d=document.createElement('dialog');d.className='welcome-dialog';d.setAttribute('aria-labelledby','welcome-title');d.innerHTML=`<button type="button" class="welcome-close" aria-label="Đóng lời chào" title="Đóng">×</button><div class="welcome-nature" aria-hidden="true">${svgIcon('leaf')}${svgIcon('leaf')}${svgIcon('leaf')}</div><div class="completion-fireworks" aria-hidden="true"></div><div class="welcome-content"><div class="welcome-lotus" aria-hidden="true">❀</div><p class="eyebrow">${esc(time.label)} · MỘT ĐIỀU ĐỂ CHIÊM NGHIỆM</p><h2 id="welcome-title">Chào mừng bạn trở lại</h2>${profile?'<div class="wisdom-teacher">'+(profile.image?'<img src="'+esc(profile.image)+'" alt="Chân dung tư liệu: '+esc(profile.name)+'" width="88" height="88">':'<span class="wisdom-initial" aria-label="Chưa có ảnh chân dung">'+esc(profile.name.split(' ').map(w=>w[0]).slice(0,2).join(''))+'</span>')+'<span><strong>'+esc(profile.name)+'</strong><small>'+esc(profile.theme)+'</small></span></div>':''}<p class="wisdom-kind">${esc(q.translationNote||'Bản dịch tiếng Việt · tham khảo')}</p><blockquote lang="vi">${esc(q.vi)}</blockquote><p class="wisdom-author">— ${esc(q.attribution||q.author)}</p><a href="${esc(q.url)}" target="_blank" rel="noopener noreferrer">${esc(q.source)} ↗</a>${q.contextUrl?'<a href="'+esc(q.contextUrl)+'" target="_blank" rel="noopener noreferrer">Giải nghĩa ẩn dụ trong kinh ↗</a>':''}${profile?.imageSource?'<a href="'+esc(profile.imageSource)+'" target="_blank" rel="noopener noreferrer">Nguồn ảnh / chân dung lịch sử ↗</a>':''}<details class="wisdom-directory"><summary>Thư viện ${wisdomCache.filter(q=>q.kind!=='reflection').length}/3.333 trích đoạn có nguồn · ${wisdomCache.filter(q=>q.kind==='reflection').length} lời biên soạn · ${(teacherCache?.profiles||[]).length} hồ sơ</summary><p>Mục tiêu 3.333 trích đoạn đang được bổ sung. Bản dịch nghĩa cần tiếp tục rà soát. Lời biên soạn được ghi rõ là của Zen Studio, lấy cảm hứng từ chủ đề tư tưởng; không phải phát ngôn của vị thầy. Chân dung cổ đại là tranh/tư liệu lịch sử. Nguồn tư liệu không đồng nghĩa với website chính thức của tác giả.</p>${(teacherCache?.profiles||[]).map(p=>'<a href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer"><strong>'+esc(p.name)+'</strong> · '+esc(p.theme)+'<small>'+esc(p.sourceType)+'</small></a>').join('')}${(teacherCache?.resources||[]).map(p=>'<a href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer">'+esc(p.name)+' · Kho tư liệu</a>').join('')}</details><p class="welcome-bottom">Hít thở chậm. Bắt đầu bằng một việc nhỏ.</p></div>`;document.body.append(d);d.addEventListener('close',()=>d.remove());d.querySelector('.welcome-close').onclick=()=>d.close();const portrait=d.querySelector('.wisdom-teacher img');if(portrait)portrait.addEventListener('error',()=>{const fallback=document.createElement('span');fallback.className='wisdom-initial';fallback.setAttribute('aria-label','Chưa tải được chân dung');fallback.textContent=profile.name.split(' ').map(w=>w[0]).slice(0,2).join('');portrait.replaceWith(fallback);},{once:true});d.showModal();welcomeSession.add(key);localWrite(key,'seen');if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const layer=d.querySelector('.completion-fireworks');for(let burst=0;burst<3;burst++)for(let i=0;i<16;i++){const angle=i/16*Math.PI*2,p=document.createElement('i');p.className='completion-particle';p.style.cssText=`left:${20+burst*30}%;top:${25+burst*10}%;--dx:${Math.cos(angle)*100}px;--dy:${Math.sin(angle)*100}px;--delay:${burst*180}ms;--particle:${['#86aa8c','#d6ac68','#c39cc6'][burst]}`;layer.append(p);}setTimeout(()=>layer.remove(),2500);}}catch{}finally{welcomeLoading=false;}}
