function noticeSignature(t){return [t.id,t.notice,t.due||'',t.title,t.important].join('|');}
function seenNotices(){try{return JSON.parse(localRead('zen-notices:'+currentUser?.id)||'[]');}catch{return [];}}
function markNoticesRead(){localWrite('zen-notices:'+currentUser?.id,JSON.stringify(taskNotices().map(noticeSignature)));fileAlerts=[];localWrite(releaseKey(),latestVersion);refreshBell();}
